import 'package:flutter/material.dart'; import '../models/user.dart'; import '../services/api.dart'; import '../widgets.dart'; import 'login.dart';
class Profile extends StatefulWidget{final User user;const Profile({super.key,required this.user});@override State<Profile> createState()=>_ProfileState();}
class _ProfileState extends State<Profile>{late final n=TextEditingController(text:widget.user.name),b=TextEditingController(text:widget.user.bio);@override void dispose(){n.dispose();b.dispose();super.dispose();}Future<void>save()async{try{await Api.patch('/users/me',{'name':n.text.trim(),'bio':b.text.trim(),'profilePic':widget.user.profilePic});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Profile saved')));}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$x')));}}@override Widget build(BuildContext c)=>ListView(padding:EdgeInsets.zero,children:[GradientHeader(title:'Your profile',subtitle:'Make your campus identity yours'),Padding(padding:const EdgeInsets.all(20),child:Column(children:[Avatar(name:n.text,size:92),const SizedBox(height:22),Text(n.text,style:const TextStyle(fontSize:24,fontWeight:FontWeight.w900)),Text(widget.user.email,style:TextStyle(color:Colors.grey.shade600)),const SizedBox(height:24),TextField(controller:n,decoration:const InputDecoration(labelText:'Display name',filled:true)),const SizedBox(height:12),TextField(controller:b,maxLines:4,decoration:const InputDecoration(labelText:'Bio',filled:true)),const SizedBox(height:18),SizedBox(width:double.infinity,height:52,child:FilledButton(onPressed:save,child:const Text('Save profile'))),const SizedBox(height:10),TextButton.icon(onPressed:()async{await Api.logout();if(!mounted)return;Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>const Login()),(_)=>false);},icon:const Icon(Icons.logout),label:const Text('Log out'))]))]);}
